 1	xfs_attr3_leaf_create(
 2		struct xfs_da_args	*args,
 3		xfs_dablk_t		blkno,
 4		struct xfs_buf		**bpp)
 5	{
 6		struct xfs_attr_leafblock *leaf;
 7		struct xfs_attr3_icleaf_hdr ichdr;
 8		struct xfs_inode	*dp = args->dp;
 9		struct xfs_mount	*mp = dp->i_mount;
10		struct xfs_buf		*bp;
11		int			error;
12	
13		trace_xfs_attr_leaf_create(args);
14	
15		error = xfs_da_get_buf(args->trans, args->dp, blkno, -1, &bp,
16						    XFS_ATTR_FORK);
17		if (error)
18			return error;
19		bp->b_ops = &xfs_attr3_leaf_buf_ops;
20		xfs_trans_buf_set_type(args->trans, bp, XFS_BLFT_ATTR_LEAF_BUF);
21		leaf = bp->b_addr;
22		memset(leaf, 0, args->geo->blksize);
23	
24		memset(&ichdr, 0, sizeof(ichdr));
25		ichdr.firstused = args->geo->blksize;
26	
27		if (xfs_sb_version_hascrc(&mp->m_sb)) {
28			struct xfs_da3_blkinfo *hdr3 = bp->b_addr;
29	
30			ichdr.magic = XFS_ATTR3_LEAF_MAGIC;
31	
32			hdr3->blkno = cpu_to_be64(bp->b_bn);
33			hdr3->owner = cpu_to_be64(dp->i_ino);
34			uuid_copy(&hdr3->uuid, &mp->m_sb.sb_meta_uuid);
35	
36			ichdr.freemap[0].base = sizeof(struct xfs_attr3_leaf_hdr);
37		} else {
38			ichdr.magic = XFS_ATTR_LEAF_MAGIC;
39			ichdr.freemap[0].base = sizeof(struct xfs_attr_leaf_hdr);
40		}
41		ichdr.freemap[0].size = ichdr.firstused - ichdr.freemap[0].base;
42	
43		xfs_attr3_leaf_hdr_to_disk(args->geo, leaf, &ichdr);
44		xfs_trans_log_buf(args->trans, bp, 0, args->geo->blksize - 1);
45	
46		*bpp = bp;
47		return 0;
48	}

